package com.demo.volunteer.portal;

import java.time.LocalDateTime;

public class PortalSummaryEntity {
    private Long id;
    private String code;
    private String name;
    private String category;
    private String status;
    private String owner;
    private String description;
    private LocalDateTime createdAt;
    private LocalDateTime updatedAt;

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getCode() { return code; }
    public void setCode(String code) { this.code = code; }
    public String getName() { return name; }
    public void setName(String name) { this.name = name; }
    public String getCategory() { return category; }
    public void setCategory(String category) { this.category = category; }
    public String getStatus() { return status; }
    public void setStatus(String status) { this.status = status; }
    public String getOwner() { return owner; }
    public void setOwner(String owner) { this.owner = owner; }
    public String getDescription() { return description; }
    public void setDescription(String description) { this.description = description; }
    public LocalDateTime getCreatedAt() { return createdAt; }
    public void setCreatedAt(LocalDateTime createdAt) { this.createdAt = createdAt; }
    public LocalDateTime getUpdatedAt() { return updatedAt; }
    public void setUpdatedAt(LocalDateTime updatedAt) { this.updatedAt = updatedAt; }
}

package com.demo.volunteer.portal;

import java.util.ArrayList;
import java.util.List;

public class PortalSummaryService {
    private final List<PortalSummaryEntity> repository = new ArrayList<>();

    public List<PortalSummaryEntity> recent(int limit) {
        List<PortalSummaryEntity> rows = new ArrayList<>();
        for (int i = 0; i < limit; i++) {
            PortalSummaryEntity entity = new PortalSummaryEntity();
            entity.setId((long) i);
            entity.setCode("PORTAL-" + i);
            entity.setName("志愿活动" + i);
            entity.setStatus("ACTIVE");
            rows.add(entity);
        }
        return rows;
    }

    public PortalSummaryEntity detail(Long id) {
        PortalSummaryEntity entity = new PortalSummaryEntity();
        entity.setId(id);
        entity.setName("志愿活动详情");
        return entity;
    }
}

